const RAD = Math.PI / 180
const miller = (lat) => 1.25 * Math.log(Math.tan(Math.PI / 4 + 0.4 * lat * RAD))
const Y0 = miller(MAP.LAT_MAX)
const SPAN = Y0 - miller(MAP.LAT_MIN)

// [lat, lon] -> [x, y] in the map's viewBox.
export function project([lat, lon]) {
    const x = (((((lon - MAP.LON0) % 360) + 360) % 360) / 360) * MAP.W
    const y = ((Y0 - miller(Math.max(MAP.LAT_MIN, Math.min(MAP.LAT_MAX, lat)))) / SPAN) * MAP.H
    return [x, y]
}

