// Names that only contain a region ("Asia Pacific", "Southern Europe") fall back to that region.
const FALLBACK = ['middle east', 'indian subcontinent', 'latin america', 'south america', 'central america', 'caribbean', 'southeast asia', 'south east asia', 'far east', 'south pacific', 'oceania', 'australia', 'africa', 'europe', 'asia']

const normalize = (name) =>
    String(name || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/&/g, ' and ')
        .replace(/[^a-z0-9]+/g, ' ')
        .trim()

export function placeFor(name) {
    const key = normalize(name)
    if (PLACES[key]) return PLACES[key]
    const bare = key.replace(/^(the|isle of|republic of) /, '')
    if (PLACES[bare]) return PLACES[bare]
    const region = FALLBACK.find((word) => key.includes(word))
    return region ? PLACES[region] : null
}
